using FlexExtractor;
namespace FlexExtractor.UI;
public sealed class StationEditor:Form {
 bool refreshing,closing;CancellationTokenSource? cancel;Task? refreshingTask;public Station Edited{get;private set;} readonly Config config;readonly TextBox name=new(){Name="StationName"},token=new(){Name="StationToken"},folder=new(){Name="SaveFolder"};readonly TreeView tree=new(){Name="SubFolders",CheckBoxes=true,Dock=DockStyle.Fill};readonly Label status=new(){Text="未勾选 = 全部；勾选父目录包含下层",AutoSize=true};
 public StationEditor(Config c,Station source){config=c;Edited=System.Text.Json.JsonSerializer.Deserialize<Station>(System.Text.Json.JsonSerializer.Serialize(source,Config.Json),Config.Json)!;Ui.Shell(this,"站位与子目录",new Size(920,620));var grid=Ui.Fields();name.Text=source.StationName;token.Text=source.Token;folder.Text=source.SaveFolder;Ui.Row(grid,"站位显示名称",name);Ui.Row(grid,"匹配规则",token);Ui.Row(grid,"规则示例",new Label{Text="31 / 0031 / 完整站位名 / * 或 all",AutoSize=true});Ui.Row(grid,"本机保存目录",folder,Ui.Action("选择…","BrowseSave",(_,_)=>Ui.Browse(folder)));Ui.Row(grid,"提取子目录",status,Ui.Action("刷新子目录","RefreshSubFolders",async(_,_)=>await RefreshAsync()));var row=grid.RowCount++;grid.RowStyles.Add(new(SizeType.Percent,100));grid.Controls.Add(tree,0,row);grid.SetColumnSpan(tree,3);var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=58,Padding=new Padding(14,6,14,6),FlowDirection=FlowDirection.RightToLeft};actions.Controls.Add(Ui.Action("确定","SaveStation",(_,_)=>Save(),true));actions.Controls.Add(Ui.Action("取消","CancelStation",(_,_)=>DialogResult=DialogResult.Cancel));Controls.Add(grid);Controls.Add(actions);Fill(source.SubFolders,source.SubFolders);FormClosing+=async(_,e)=>{if(!refreshing||closing)return;e.Cancel=true;cancel!.Cancel();if(refreshingTask!=null)await refreshingTask;closing=true;Close();};}
 public Task RefreshAsync(){if(refreshing)return refreshingTask!;refreshing=true;cancel=new();refreshingTask=RefreshCoreAsync(cancel.Token);return refreshingTask;}
 async Task RefreshCoreAsync(CancellationToken cancellation){try{status.Text="正在刷新；可取消关闭";var selected=Nodes(tree.Nodes).Where(x=>x.Checked).Select(x=>x.Name).ToArray();var cfg=Config.Parse(System.Text.Json.JsonSerializer.Serialize(config,Config.Json));cfg.DispenseItems=[new Station{Token=token.Text.Trim(),StationName=name.Text.Trim(),SaveFolder=Path.Combine(MachineState.Root,"discovery-unused")}];cfg.BindItems=[];cfg.Validate();using var owner=new OwnerLease();var result=await WorkerRunner.RunAsync(owner,cfg,"discover",DateTime.UtcNow,cancellation);if(result.Failed>0){status.Text=string.Join(" | ",result.Messages);return;}Fill(result.Folders.Union(selected,StringComparer.OrdinalIgnoreCase),selected);status.Text=$"发现 {result.Folders.Count} 个目录；未勾选 = 全部";}
 catch(Exception ex)when(ex is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException){status.Text="刷新失败："+ex.Message;}
 finally{refreshing=false;cancel?.Dispose();cancel=null;}}
 protected override void Dispose(bool disposing){if(disposing)cancel?.Dispose();base.Dispose(disposing);}
 void Fill(IEnumerable<string> folders,IEnumerable<string> selected){var wanted=selected.ToHashSet(StringComparer.OrdinalIgnoreCase);tree.Nodes.Clear();foreach(var value in folders.Order(StringComparer.OrdinalIgnoreCase)){var parts=value.Replace('\\','/').Split('/');TreeNodeCollection nodes=tree.Nodes;string path="";foreach(var part in parts){path=path.Length==0?part:path+"/"+part;var node=nodes.Cast<TreeNode>().FirstOrDefault(x=>x.Name==path);if(node==null){node=new TreeNode(part){Name=path,Checked=wanted.Contains(path)};nodes.Add(node);}nodes=node.Nodes;}}tree.ExpandAll();}
 IEnumerable<TreeNode> Nodes(TreeNodeCollection nodes){foreach(TreeNode n in nodes){yield return n;foreach(var x in Nodes(n.Nodes))yield return x;}}
 void Save(){try{if(refreshing)throw new InvalidDataException("刷新尚未停止");var s=new Station{StationName=name.Text.Trim(),Token=token.Text.Trim(),SaveFolder=folder.Text.Trim(),SubFolders=Nodes(tree.Nodes).Where(x=>x.Checked).Select(x=>x.Name).ToList()};var check=Config.Parse(System.Text.Json.JsonSerializer.Serialize(config,Config.Json));check.DispenseItems=[s];check.BindItems=[];check.Validate();Edited=s;DialogResult=DialogResult.OK;}catch(Exception ex)when(ex is InvalidDataException or ArgumentException){Ui.Error(this,ex);}}

}
